package com.aadil.ecommerce.services;import com.aadil.ecommerce.UserRole;import com.aadil.ecommerce.entities.UserEntity;import com.aadil.ecommerce.repositories.UserRepository;import org.jspecify.annotations.NonNull;import org.springframework.security.core.userdetails.User;import org.springframework.security.core.userdetails.UserDetails;import org.springframework.security.core.userdetails.UserDetailsService;import org.springframework.security.core.userdetails.UsernameNotFoundException;import org.springframework.stereotype.Service;@Servicepublic class SecurityUserDetailService implements UserDetailsService {    private final UserRepository userRepository;    public SecurityUserDetailService(UserRepository userRepository) {        this.userRepository = userRepository;    }    @Override    public UserDetails loadUserByUsername(@NonNull String username) throws UsernameNotFoundException {        UserEntity user = userRepository.findByEmail(username).                orElseThrow(()->new UsernameNotFoundException("Username NOT found: "+username));        return User.withUsername(user.getEmail()).password(user.getPassword()).roles(UserRole.USER.name()).build();    }}